
async function enrol(db,user='player-a',values={}){const draft=(await api(db,'/api/planet-enrolment','GET',null,user)).data;const result=await api(db,'/api/planet-enrolment','POST',{generation:draft.generation,confirmation:true,ruler:'New Ruler',planetName:'New Colony',race:'Terran',theme:'Neutral',...values},user);assert.equal(result.status,200);return result;}
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const {DatabaseSync}=require('node:sqlite');
const portalSource=fs.readFileSync(path.join(__dirname,'../worker/portal.js'),'utf8');
