test('player-only cleanup removes NPC planets and alliances while preserving player reservations',async()=>{const db=database();await seed(db);const body=world();body.revision=1;body.planets.push({id:'npc',name:'NPC',ruler:'NPC',coords:'07:04:02',race:'Terran',alliance:'NPC Guild'});body.alliances.push({name:'NPC Guild',members:[]});await api(db,'/api/planets','POST',body);await api(db,'/api/portal/alliance-manager','POST',{action:'reserve',name:'Reserved Guild',tag:'RES'});for(const file of ['0006_alliance_owners.sql','0007_forums.sql','0009_alliance_fleets.sql','0010_key_disclosure_access.sql','0013_alliance_reservations.sql'])db.sqlite.exec(fs.readFileSync(path.join(__dirname,'../drizzle',file),'utf8'));db.sqlite.exec(fs.readFileSync(path.join(__dirname,'../drizzle/0014_requested_player_only_cleanup.sql'),'utf8'));const data=(await api(db,'/api/planets')).data;assert.equal(data.playerOnly,true);assert.deepEqual(data.planets.map(p=>p.id),['home']);assert.deepEqual(data.alliances.map(a=>a.name),['Pact']);assert.equal((await api(db,'/api/portal/alliance-manager')).data.reservedCount,1);assert.equal((await api(db,'/api/planets','POST',{...body,revision:data.revision})).status,400);});
test('portal account ranks enforce separate support and multihunter permissions and retain an administrator',async()=>{const db=database();await seed(db);const rank=value=>api(db,'/api/admin/account-ranks','POST',{userId:'player-b',rank:value});assert.equal((await rank('support')).status,200);assert.equal((await api(db,'/api/tickets?queue=staff','GET',null,'player-b')).status,200);assert.equal((await api(db,'/api/admin/access-logs','GET',null,'player-b')).status,403);assert.equal((await api(db,'/api/admin/account-ranks','GET',null,'player-b')).status,403);assert.equal((await rank('multihunter')).status,200);assert.equal((await api(db,'/api/admin/access-logs','GET',null,'player-b')).status,200);assert.equal((await api(db,'/api/fleet-movements','GET',null,'player-b')).status,200);assert.equal((await api(db,'/api/tickets?queue=staff','GET',null,'player-b')).status,403);assert.equal((await api(db,'/api/portal/staff','GET',null,'player-b')).status,200);assert.equal((await api(db,'/api/admin/account-ranks','POST',{userId:'player-a',rank:'player'})).status,409);assert.equal((await rank('unknown')).status,400);assert.equal((await rank('admin')).status,200);assert.equal((await api(db,'/api/admin/account-ranks','POST',{userId:'player-a',rank:'support'})).status,200);assert.equal((await api(db,'/api/admin/account-ranks','GET',null,'player-b')).status,200);});
test('staff planet audit records committed field changes and is readable by Support and Multihunter only',async()=>{const db=database();await seed(db);const changed=world();changed.revision=1;changed.source='staff-editor';changed.planets[0].name='Edited Home';changed.planets[0].resources.metal=321;changed.planets[0].passphrase='fixture-secret-not-in-audit';assert.equal((await api(db,'/api/planets','POST',changed)).status,200);let data=(await api(db,'/api/admin/planet-audit?planet=Edited')).data;assert.equal(data.records.length,1);assert.equal(data.records[0].actor_name,'player-a');assert.ok(data.records[0].changes.fields.some(c=>c.field==='resources.metal'&&c.old==='123'&&c.new==='321'));assert.doesNotMatch(JSON.stringify(data),/fixture-secret-not-in-audit/);const before=(await api(db,'/api/admin/planet-audit')).data.records.length;assert.equal((await api(db,'/api/planets','POST',changed)).status,409);assert.equal((await api(db,'/api/admin/planet-audit')).data.records.length,before);assert.equal((await api(db,'/api/admin/planet-audit','GET',null,'player-b')).status,403);for(const rank of ['support','multihunter']){await api(db,'/api/admin/account-ranks','POST',{userId:'player-b',rank});assert.equal((await api(db,'/api/admin/planet-audit','GET',null,'player-b')).status,200);assert.equal((await api(db,'/api/planets','POST',changed,'player-b')).status,403);}});

test('attack claims are alliance-private and administrators cannot bypass one active claim',async()=>{const db=database();await seed(db);let r=await api(db,'/api/alliance-attack','POST',{action:'create',coords:'07:04:02',title:'First target',notes:''});assert.equal(r.status,200);assert.equal((await api(db,'/api/alliance-attack','POST',{action:'create',coords:'07:04:02',title:'Duplicate',notes:''})).status,409);await api(db,'/api/alliance-attack','POST',{action:'create',coords:'07:04:03',title:'Second target',notes:''});const targets=(await api(db,'/api/alliance-attack')).data.targets;assert.equal((await api(db,'/api/alliance-attack','GET',null,'player-b')).status,403);assert.equal((await api(db,'/api/alliance-attack','POST',{action:'claim',id:targets[0].id})).status,200);assert.equal((await api(db,'/api/alliance-attack','POST',{action:'claim',id:targets[0].id})).status,409);assert.equal((await api(db,'/api/alliance-attack','POST',{action:'claim',id:targets[1].id})).status,409);assert.equal((await api(db,'/api/alliance-attack','POST',{action:'release',id:targets[0].id})).status,200);assert.equal((await api(db,'/api/alliance-attack','POST',{action:'claim',id:targets[1].id})).status,200);assert.equal((await api(db,'/api/alliance-attack','POST',{action:'close',id:targets[1].id})).status,200);assert.equal((await api(db,'/api/alliance-attack')).data.hasClaim,false);assert.equal((await api(db,'/api/alliance-attack','POST',{action:'claim',id:targets[0].id},'player-a','https://evil.test')).status,403);});
