test('reset requires enrolment and restores type-based population empty buildings research and stopped ticks',async()=>{const db=database();await seed(db);await api(db,'/api/portal/reset','POST',{confirmation:'RESET'});assert.equal((await api(db,'/api/planets')).data.planets.length,0);const draft=(await api(db,'/api/planet-enrolment')).data;await enrol(db);const mine=(await api(db,'/api/planets')).data.planets.find(p=>p.player);assert.equal(mine.population,draft.planetType.basePopulation);assert.ok(Object.values(mine.buildings).every(n=>n===0));assert.ok(Object.values(mine.research).every(n=>n===0));assert.deepEqual(mine.workforce,{mining:0,research:0,construction:0,shipwright:0,security:0});assert.equal(mine.tickerRunning,false);assert.equal(mine.publicTick,1);});

test('enrolment fixes a private random world and requires confirmation before creating one starting planet',async()=>{const db=database();await seed(db);const first=await api(db,'/api/planet-enrolment','GET',null,'player-b'),again=await api(db,'/api/planet-enrolment','GET',null,'player-b');assert.equal(first.data.planetType.id,again.data.planetType.id);assert.equal(db.sqlite.prepare('SELECT count(*) n FROM planet_directory WHERE owner_id=?').get('player-b').n,0);assert.equal((await api(db,'/api/planet-enrolment','POST',{generation:0,confirmation:false},'player-b')).status,409);await enrol(db,'player-b',{race:'Cathaar',theme:'AstraNexus'});const p=JSON.parse(db.sqlite.prepare('SELECT data_json FROM planet_directory WHERE owner_id=?').get('player-b').data_json);assert.equal(p.planetType,first.data.planetType.id);assert.equal(p.population,first.data.planetType.basePopulation);assert.equal(p.race,'Cathaar');assert.equal(p.theme,first.data.planetType.theme||'AstraNexus');assert.equal(p.startingGalaxy,true);assert.match(p.coords,/^01:/);assert.equal((await api(db,'/api/planet-enrolment','POST',{generation:0,confirmation:true},'player-b')).status,409);});
test('population levy permission is enforced and resident allowance accrues without replay collection',async()=>{const db=database();await seed(db);const home=JSON.parse(db.sqlite.prepare('SELECT data_json FROM planet_directory WHERE id=?').get('home').data_json);home.population=501;home.publicPopulation=501;home.publicTick=1;db.sqlite.prepare('UPDATE planet_directory SET data_json=? WHERE id=?').run(JSON.stringify(home),'home');let d=(await api(db,'/api/galaxy-development')).data;assert.equal(d.tax,0);assert.equal(d.canView,true);assert.equal(d.canEdit,false);assert.equal((await api(db,'/api/galaxy-development','POST',{action:'tax',rate:1,generation:0})).status,403);const ministers={communication:'',development:home.ruler,war:'',economics:home.ruler,scanner:''};assert.equal((await api(db,'/api/galaxy-development','POST',{action:'ministers',ministers,generation:0})).status,200);assert.equal((await api(db,'/api/galaxy-development','POST',{action:'tax',rate:1,generation:0})).status,200);const report={...colonyFixture(501,0),publicTick:2};assert.equal((await api(db,'/api/colony','POST',report)).status,200);d=(await api(db,'/api/galaxy-development')).data;assert.equal(d.history[0].removed,0);assert.equal(d.fund.metal,0);assert.ok(Math.abs(d.ownTax.carry-1/24)<1e-8);assert.equal((await api(db,'/api/colony','POST',report)).status,200);const settled=JSON.parse(db.sqlite.prepare('SELECT data_json FROM planet_directory WHERE id=?').get('home').data_json);assert.equal(settled.population,501);assert.equal(settled.populationTaxTotal,0);assert.equal((await api(db,'/api/galaxy-development','POST',{action:'tax',rate:0,generation:0})).status,200);});
test('manual shuffle is admin-only and creates unique regular galaxy coordinates',async()=>{const db=database();await seed(db);await enrol(db,'player-b');assert.equal((await api(db,'/api/admin/shuffle','POST',{confirmation:'SHUFFLE'},'player-b')).status,403);assert.equal((await api(db,'/api/admin/shuffle','POST',{confirmation:'NO'})).status,400);const before=(await api(db,'/api/planets')).data.planets.map(p=>p.id).sort();const shuffled=await api(db,'/api/admin/shuffle','POST',{confirmation:'SHUFFLE'});assert.equal(shuffled.status,200);assert.equal(shuffled.data.planets,2);const after=(await api(db,'/api/planets')).data.planets;assert.deepEqual(after.map(p=>p.id).sort(),before);assert.equal(new Set(after.map(p=>p.coords)).size,2);assert.ok(after.every(p=>p.coords.startsWith('02:')&&!p.startingGalaxy));});
test('recruit requests reach the alliance, reject duplicates and require authorised acceptance',async()=>{const db=database();await seed(db);await enrol(db,'player-b');let known=await api(db,'/api/alliance-applications','GET',null,'player-b');assert.ok(known.data.alliances.some(a=>a.name==='Pact'));const application={action:'apply',alliance:'Pact',message:'Ready to serve',generation:0};assert.equal((await api(db,'/api/alliance-applications','POST',application,'player-b')).status,200);assert.equal((await api(db,'/api/alliance-applications','POST',application,'player-b')).status,409);let a=JSON.parse(db.sqlite.prepare('SELECT data_json FROM planet_alliances WHERE name=?').get('Pact').data_json);assert.equal(a.applicants[0].rank,'Recruit');const id=a.applicants[0].id;assert.equal((await api(db,'/api/alliance-applications','POST',{action:'accept',applicationId:id,generation:0},'player-b')).status,403);assert.equal((await api(db,'/api/alliance-applications','POST',{action:'accept',applicationId:id,generation:0})).status,200);a=JSON.parse(db.sqlite.prepare('SELECT data_json FROM planet_alliances WHERE name=?').get('Pact').data_json);assert.equal(a.members.find(m=>m.planetId==='player-player-b').rank,'Recruit');assert.equal(a.applicants.length,0);});

test('automatic distribution happens exactly once at tick 12 and retains colony assets',async()=>{const db=database();await seed(db);await enrol(db,'player-b');let report=colonyFixture(500,0);report.publicTick=11;assert.equal((await api(db,'/api/colony','POST',report)).status,200);assert.equal((await api(db,'/api/admin/shuffle')).data.shuffled,false);report.publicTick=12;assert.equal((await api(db,'/api/colony','POST',report)).status,200);const status=(await api(db,'/api/admin/shuffle')).data;assert.equal(status.shuffled,true);assert.equal(status.atTick,12);const coords=(await api(db,'/api/planets')).data.planets.map(p=>p.coords);report.publicTick=13;assert.equal((await api(db,'/api/colony','POST',report)).status,200);assert.deepEqual((await api(db,'/api/planets')).data.planets.map(p=>p.coords),coords);});
test('requested publication reset migration empties every planet and creates different pending charters',()=>{const db=new DatabaseSync(':memory:');for(const name of fs.readdirSync(path.join(__dirname,'../drizzle')).filter(n=>n.endsWith('.sql')&&!n.startsWith('0018')&&!n.startsWith('0024')).sort())db.exec(fs.readFileSync(path.join(__dirname,'../drizzle',name),'utf8'));db.prepare('INSERT INTO portal_users(id,username,password_hash,password_salt,role,created_at) VALUES(?,?,?,?,?,?)').run('kept','KeptAccount','hash','salt','admin',1);db.prepare('INSERT INTO planet_directory VALUES(?,?,?,?,?,?)').run('old','planet','01:01:01','kept',JSON.stringify({id:'old',planetType:'planet-01',population:1000}),1);db.prepare('INSERT INTO planet_directory VALUES(?,?,?,?,?,?)').run('dummy','planet','01:01:02',null,JSON.stringify({id:'dummy'}),1);db.exec(fs.readFileSync(path.join(__dirname,'../drizzle/0018_requested_charter_round_reset.sql'),'utf8'));assert.equal(db.prepare('SELECT count(*) n FROM planet_directory').get().n,0);assert.equal(db.prepare('SELECT count(*) n FROM portal_users').get().n,1);const charter=db.prepare('SELECT * FROM planet_enrolments').get();assert.notEqual(charter.planet_type,'planet-01');assert.equal(charter.confirmed,0);assert.equal(charter.generation,db.prepare('SELECT reset_generation FROM planet_directory_meta').get().reset_generation);});

test('world rerolls persist across refresh, stop at three and reject stale review',async()=>{const db=database();await seed(db);let draft=(await api(db,'/api/planet-enrolment','GET',null,'player-b')).data;assert.equal(draft.rerollsRemaining,3);const initial=draft.planetType.id;for(let i=0;i<3;i++){const rolled=await api(db,'/api/planet-enrolment','POST',{action:'reroll',generation:draft.generation},'player-b');assert.equal(rolled.status,200);assert.equal(rolled.data.rerollsRemaining,2-i);const fresh=(await api(db,'/api/planet-enrolment','GET',null,'player-b')).data;assert.equal(fresh.planetType.id,rolled.data.planetType.id);assert.equal(fresh.rerollsRemaining,2-i);draft=fresh;}assert.equal((await api(db,'/api/planet-enrolment','POST',{action:'reroll',generation:draft.generation},'player-b')).status,409);assert.equal((await api(db,'/api/planet-enrolment','POST',{generation:draft.generation,planetType:initial,confirmation:true,ruler:'Stale Ruler',planetName:'Stale World',race:'Terran',theme:'Neutral'},'player-b')).status,409);});
test('unique Arrakis charter auto-applies its private theme and broadcasts no holder identity',async()=>{const db=database();await seed(db);const worlds=require('../dist/planet-catalog.json'),arrakis=worlds.find(t=>t.name==='Arrakis');await api(db,'/api/planet-enrolment','GET',null,'player-b');db.sqlite.prepare('UPDATE planet_enrolments SET planet_type=?,unique_key=? WHERE user_id=?').run(arrakis.id,arrakis.uniqueKey,'player-b');const result=await enrol(db,'player-b',{ruler:'Hidden Holder',planetName:'Other Name'});assert.equal(result.data.theme,'UltimateWorld');const p=JSON.parse(db.sqlite.prepare('SELECT data_json FROM planet_directory WHERE owner_id=?').get('player-b').data_json);assert.equal(p.name,'Other Name');const news=(await api(db,'/api/world-announcements')).data;assert.equal(news.announcements.length,1);assert.equal(news.announcements[0].etaBonus,-1);assert.doesNotMatch(JSON.stringify(news),/Hidden Holder|player-b|01:01:/);assert.equal((await api(db,'/api/planets','PATCH',{planetName:'Rename Arrakis'},'player-b')).status,200);assert.equal((await api(db,'/api/portal/profile','POST',{displayName:'player-b',theme:'BorgWorld'},'player-b')).status,400);assert.equal((await api(db,'/api/portal/profile','GET',null,'player-b')).data.allowedThemes.includes('UltimateWorld'),true);});
test('Earth salvage credits only its owner from both sides, once, and refuses simulations',async()=>{const db=database();await seed(db);seedOtherAlliance(db);const row=db.sqlite.prepare('SELECT data_json FROM planet_directory WHERE owner_id=?').get('player-b'),p=JSON.parse(row.data_json);p.planetType=require('../dist/planet-catalog.json').find(t=>t.name==='Earth').id;p.name='Earth';p.resources={metal:100,crystal:100,eonium:100};db.sqlite.prepare('UPDATE planet_directory SET data_json=? WHERE owner_id=?').run(JSON.stringify(p),'player-b');const report={id:'battle-earth-test-1',generation:0,targetId:p.id,attacker:{'terran-lumen':10},survivorsA:{'terran-lumen':8},defender:{'terran-aegis':10},survivorsD:{'terran-aegis':7}};const first=await api(db,'/api/earth-salvage','POST',report);assert.equal(first.status,200);assert.equal(first.data.award.metal,Math.floor((2*169+3*271)*.2));const total=JSON.parse(db.sqlite.prepare('SELECT data_json FROM planet_directory WHERE owner_id=?').get('player-b').data_json).resources.metal;assert.equal(total,100+first.data.award.metal);assert.equal((await api(db,'/api/earth-salvage','POST',report)).data.duplicate,true);assert.equal(JSON.parse(db.sqlite.prepare('SELECT data_json FROM planet_directory WHERE owner_id=?').get('player-b').data_json).resources.metal,total);assert.equal((await api(db,'/api/earth-salvage','POST',{...report,id:'battle-earth-test-2',simulated:true})).status,400);});
test('Spacing Bank starts funded, enforces limits and tax, settles once and restarts reserves per round',async()=>{const db=database();await seed(db);const funded=JSON.parse(db.sqlite.prepare('SELECT data_json FROM planet_directory WHERE id=?').get('home').data_json);funded.resources={metal:2000,crystal:2000,eonium:2000};db.sqlite.prepare('UPDATE planet_directory SET data_json=? WHERE id=?').run(JSON.stringify(funded),'home');let bank=(await api(db,'/api/spacing-bank')).data;assert.equal(bank.balances.crystal,1000000);assert.equal(bank.settings.tax,5);assert.equal((await api(db,'/api/spacing-bank','POST',{action:'configure',settings:{...bank.settings,tax:5}},'player-b')).status,403);assert.equal((await api(db,'/api/spacing-bank','POST',{action:'configure',settings:{...bank.settings,tax:5,starting:{metal:2000000,crystal:2000000,eonium:2000000}}})).status,200);bank=(await api(db,'/api/spacing-bank')).data;assert.equal(bank.balances.metal,1000000);const body={action:'trade',id:'bank-trade-test-001',generation:bank.generation,revision:bank.revision,from:'metal',to:'crystal',amount:1000};const first=await api(db,'/api/spacing-bank','POST',body);assert.equal(first.status,200);assert.equal(first.data.trade.receive,950);assert.equal(first.data.trade.fee,50);const balances=(await api(db,'/api/spacing-bank')).data;assert.equal(balances.balances.crystal,999050);assert.equal((await api(db,'/api/spacing-bank','POST',{...body,revision:balances.revision})).data.duplicate,true);assert.equal((await api(db,'/api/spacing-bank','POST',{...body,id:'bank-trade-test-002',revision:balances.revision,amount:100001})).status,400);db.sqlite.prepare('UPDATE planet_directory_meta SET reset_generation=reset_generation+1 WHERE id=1').run();const reset=(await api(db,'/api/spacing-bank')).data;assert.equal(reset.balances.metal,2000000);assert.equal(reset.volume,0);});

test('public five-character account IDs are unique, stable, read-only and staff pages need no planet',async()=>{const db=database();await seed(db);const a=(await api(db,'/api/portal/profile')).data.user,b=(await api(db,'/api/portal/profile','GET',null,'player-b')).data.user;assert.match(a.accountId,/^[A-Z0-9]{5}$/);assert.match(b.accountId,/^[A-Z0-9]{5}$/);assert.notEqual(a.accountId,b.accountId);db.sqlite.prepare('DELETE FROM planet_directory').run();assert.equal((await api(db,'/api/portal/profile','POST',{displayName:'player-b',theme:'Neutral',accountId:'XXXXX'},'player-b')).status,200);assert.equal((await api(db,'/api/portal/profile','GET',null,'player-b')).data.user.accountId,b.accountId);const {default:worker}=await workerPromise;const response=await worker.fetch(new Request('https://starfall.test/game?staff_workspace=1&staff_tool=control',{headers:{Cookie:'starfall_session='+'a'.repeat(64)}}),{DB:db});assert.notEqual(response.status,302);assert.notEqual(response.status,403);assert.equal((await api(db,'/api/staff-directory','GET',null,null)).status,200);const roster=(await api(db,'/api/staff-directory','GET',null,null)).data;assert.equal(roster.staff.length,1);assert.equal(roster.staff[0].title,'Command Administrator');assert.doesNotMatch(JSON.stringify(roster),/password|salt|owner|token_hash/);});

test('site test flags are centrally saved, admin protected and revision checked',async()=>{const db=database();await seed(db);const flags=(await api(db,'/api/site-management','GET',null,null)).data;assert.equal(flags.roundHistoryDemo,true);assert.equal((await api(db,'/api/site-management','POST',{revision:flags.revision,roundHistoryDemo:false,battleCalcTest:false},'player-b')).status,403);assert.equal((await api(db,'/api/site-management','POST',{revision:flags.revision,roundHistoryDemo:false,battleCalcTest:false})).status,200);assert.equal((await api(db,'/api/site-management','GET',null,null)).data.battleCalcTest,false);assert.equal((await api(db,'/api/site-management','POST',{revision:flags.revision,roundHistoryDemo:true,battleCalcTest:true})).status,409);assert.equal((await api(db,'/api/round-history','GET',null,null)).data.rounds.length,0);});

test('requested final release reset renews rerolls and releases rare reservations without deleting accounts',()=>{const db=new DatabaseSync(':memory:');for(const name of fs.readdirSync(path.join(__dirname,'../drizzle')).filter(n=>n.endsWith('.sql')&&!n.startsWith('0024')).sort())db.exec(fs.readFileSync(path.join(__dirname,'../drizzle',name),'utf8'));db.prepare('INSERT INTO portal_users(id,username,password_hash,password_salt,role,created_at,account_id) VALUES(?,?,?,?,?,?,?)').run('kept','Keeper','fixture','fixture','admin',1,'A1234');db.prepare('INSERT INTO planet_directory VALUES(?,?,?,?,?,?)').run('old','planet','01:01:01','kept',JSON.stringify({planetType:'unimatrix999-homeworld',population:1049}),1);db.exec(fs.readFileSync(path.join(__dirname,'../drizzle/0024_requested_feature_round_reset.sql'),'utf8'));assert.equal(db.prepare('SELECT count(*) n FROM planet_directory').get().n,0);assert.equal(db.prepare('SELECT account_id FROM portal_users').get().account_id,'A1234');const draft=db.prepare('SELECT * FROM planet_enrolments').get();assert.equal(draft.planet_type,'');assert.equal(draft.previous_type,'unimatrix999-homeworld');assert.equal(draft.rerolls,0);assert.equal(draft.unique_key,null);});

test('staff role permissions and manual routes reject escalation even without planets',async()=>{const db=database();await seed(db);db.sqlite.prepare('DELETE FROM planet_directory').run();assert.equal((await api(db,'/staff-manual.html','GET',null,'player-b')).status,403);db.sqlite.prepare('UPDATE portal_users SET role=? WHERE id=?').run('support','player-b');const session=(await api(db,'/api/portal/session','GET',null,'player-b')).data.user;assert.ok(session.permissions.includes('support'));assert.equal(session.permissions.includes('multihunter'),false);assert.equal(session.permissions.includes('bank'),false);assert.equal((await api(db,'/staff-manual-admin.html','GET',null,'player-b')).status,403);assert.equal((await api(db,'/api/site-management','POST',{revision:0,roundHistoryDemo:false,battleCalcTest:false},'player-b')).status,403);const bank=(await api(db,'/api/spacing-bank','GET',null,'player-b')).data;assert.equal(bank.canConfigure,false);assert.equal((await api(db,'/api/spacing-bank','POST',{action:'configure',settings:bank.settings},'player-b')).status,403);db.sqlite.prepare('UPDATE portal_users SET role=? WHERE id=?').run('multihunter','player-b');assert.equal((await api(db,'/api/portal/session','GET',null,'player-b')).data.user.permissions.includes('multihunter'),true);assert.equal((await api(db,'/staff-manual-support.html','GET',null,'player-b')).status,403);});
test('generated player manual omits privileged chapters and staff variants follow role scope',()=>{const read=name=>fs.readFileSync(path.join(__dirname,'../dist',name),'utf8');const player=read('manual.html');for(const id of ['staff-controlcenters','staff-news','havoc','staff-bank','staff-investigations'])assert.ok(!player.includes('id="'+id+'"'));const support=read('staff-manual-support.html'),hunter=read('staff-manual-multihunter.html'),admin=read('staff-manual-admin.html');assert.ok(support.includes('id="staff-support"'));assert.ok(!support.includes('id="havoc"'));assert.ok(!support.includes('id="staff-investigations"'));assert.ok(hunter.includes('id="staff-investigations"'));assert.ok(!hunter.includes('id="staff-support"'));assert.ok(admin.includes('id="havoc"'));assert.ok(admin.includes('id="staff-bank"'));});

test('staff diagnostics are stored, survive round cleanup and reject player access',async()=>{const db=database();await seed(db);assert.equal((await api(db,'/api/staff/diagnostics','GET',null,'player-b')).status,403);const run=await api(db,'/api/staff/diagnostics','POST',{observations:[{severity:'warning',category:'layout',page:'/portal.html',message:'Horizontal overflow'}],sampledPages:1});assert.equal(run.status,200);assert.equal(run.data.report.status,'warnings');const id=run.data.report.id;assert.equal((await api(db,'/api/staff/diagnostics')).data.reports[0].id,id);assert.equal((await api(db,'/api/staff/diagnostics?id='+id)).data.report.findings.at(-1).category,'layout');db.sqlite.prepare('DELETE FROM planet_directory').run();assert.equal((await api(db,'/api/staff/diagnostics?id='+id)).status,200);assert.equal((await api(db,'/api/staff/diagnostics','POST',{observations:Array(201).fill({})})).status,400);});

test('reference-world player names are editable without releasing their world reservation',async()=>{const db=database();await seed(db);await api(db,'/api/portal/reset','POST',{confirmation:'RESET'});const draft=(await api(db,'/api/planet-enrolment')).data;db.sqlite.prepare('UPDATE planet_enrolments SET planet_type=?,unique_key=? WHERE user_id=?').run('dune-borhees-17lpvnn','borhees','player-a');const type=(await api(db,'/api/planet-enrolment')).data.planetType;assert.ok(type);const first=await enrol(db,'player-a',{ruler:'Admiral Sol',planetName:'My Borhees Colony'});const before=(await api(db,'/api/planets')).data.planets.find(p=>p.player);assert.equal(before.name,'My Borhees Colony');assert.equal((await api(db,'/api/planets','PATCH',{planetName:'New Borhees Colony'})).status,200);const after=(await api(db,'/api/planets')).data.planets.find(p=>p.player);assert.equal(after.name,'New Borhees Colony');assert.equal(after.planetType,before.planetType);assert.equal(db.sqlite.prepare('SELECT unique_key FROM planet_enrolments WHERE user_id=?').get('player-a').unique_key,'borhees');});

test('public asset requests use one-minute caching and conditional revalidation',async()=>{const db=database();await seed(db);const {default:worker}=await workerPromise;const first=await worker.fetch(new Request('https://starfall.test/portal.html'),{DB:db});assert.equal(first.status,200);assert.equal(first.headers.get('Cache-Control'),'public, max-age=60, must-revalidate');const second=await worker.fetch(new Request('https://starfall.test/portal.html',{headers:{'If-None-Match':first.headers.get('ETag')}}),{DB:db});assert.equal(second.status,304);assert.equal(await second.text(),'');});

test('staff node configuration applies immediately, audits changes and rejects stale revisions',async()=>{const db=database();db.sqlite.prepare("UPDATE portal_users SET role='admin' WHERE id='player-a'").run();db.sqlite.prepare("UPDATE portal_users SET role='multihunter' WHERE id='player-b'").run();assert.equal((await api(db,'/api/admin/access-logs','GET',null,'player-b')).status,200);assert.equal((await api(db,'/api/admin/account-ranks','GET',null,'player-b')).status,403);const d=(await api(db,'/api/admin/account-ranks')).data,mh=d.ranks.find(r=>r.id==='multihunter');const permissions={...mh.nodes,multihunter:false,support:true};const payload={action:'permissions',role:'multihunter',revision:mh.revision,permissions};assert.equal((await api(db,'/api/admin/account-ranks','POST',payload)).status,200);assert.equal((await api(db,'/api/admin/access-logs','GET',null,'player-b')).status,403);const session=(await api(db,'/api/portal/session','GET',null,'player-b')).data;assert.equal(session.user.staffPermissions.support,true);assert.equal(session.user.staffPermissions.multihunter,false);assert.equal(db.sqlite.prepare('SELECT count(*) AS n FROM staff_permission_audit').get().n,1);assert.equal((await api(db,'/api/admin/account-ranks','POST',payload)).status,409);assert.equal(db.sqlite.prepare('SELECT count(*) AS n FROM staff_permission_audit').get().n,1);});
test('permission configuration rejects dependent reveals, unknown nodes and non-admin escalation',async()=>{const db=database();db.sqlite.prepare("UPDATE portal_users SET role='admin' WHERE id='player-a'").run();db.sqlite.prepare("UPDATE portal_users SET role='support' WHERE id='player-b'").run();const data=(await api(db,'/api/admin/account-ranks')).data,p=data.ranks.find(r=>r.id==='support').nodes;assert.equal((await api(db,'/api/admin/account-ranks','POST',{action:'permissions',role:'support',revision:0,permissions:{...p,keyReveal:true}})).status,400);assert.equal((await api(db,'/api/admin/account-ranks','POST',{action:'permissions',role:'support',revision:0,permissions:{...p,fakeNode:true}})).status,400);assert.equal((await api(db,'/api/admin/account-ranks','POST',{action:'permissions',role:'support',revision:0,permissions:{...p,ranks:true}})).status,200);assert.equal((await api(db,'/api/admin/account-ranks','POST',{action:'permissions',role:'support',revision:1,permissions:p},'player-b')).status,403);assert.equal((await api(db,'/api/admin/account-ranks','POST',{userId:'player-b',rank:'admin'},'player-b')).status,403);assert.equal((await api(db,'/api/admin/account-ranks','POST',{userId:'player-a',rank:'player'},'player-b')).status,403);});
test('delegated Admin Controlcenter permission opens its workspace and can be revoked without changing rank',async()=>{const db=database();db.sqlite.prepare("UPDATE portal_users SET role='admin' WHERE id='player-a'").run();db.sqlite.prepare("UPDATE portal_users SET role='multihunter' WHERE id='player-b'").run();assert.equal((await api(db,'/game?staff_workspace=1&staff_tool=control','GET',null,'player-b')).status,403);const d=(await api(db,'/api/admin/account-ranks')).data,p=d.ranks.find(r=>r.id==='multihunter').nodes;assert.equal((await api(db,'/api/admin/account-ranks','POST',{action:'permissions',role:'multihunter',revision:0,permissions:{...p,adminControl:true}})).status,200);assert.notEqual((await api(db,'/game?staff_workspace=1&staff_tool=control','GET',null,'player-b')).status,403);assert.equal((await api(db,'/api/admin/account-ranks','POST',{action:'permissions',role:'multihunter',revision:1,permissions:p})).status,200);assert.equal((await api(db,'/game?staff_workspace=1&staff_tool=control','GET',null,'player-b')).status,403);assert.equal(db.sqlite.prepare("SELECT role FROM portal_users WHERE id='player-b'").get().role,'multihunter');});

async function attackFixture(shared=false){const db=database();await seed(db);seedOtherAlliance(db);if(shared){const row=db.sqlite.prepare("SELECT data_json FROM planet_directory WHERE owner_id='player-b'").get(),p=JSON.parse(row.data_json);p.alliance='Pact';db.sqlite.prepare("UPDATE planet_directory SET data_json=? WHERE owner_id='player-b'").run(JSON.stringify(p));}return db;}
async function createAttack(db,extra={}){const r=await api(db,'/api/alliance-operations','POST',{action:'create',generation:0,title:'Frontier operation',notes:'Two-stage assault',landTick:40,waves:3,targets:['07:05:01'],...extra});assert.equal(r.status,200,JSON.stringify(r.data));return (await api(db,'/api/alliance-operations')).data.operations.find(o=>o.id===r.data.id);}
test('attack operations create consecutive wave bookings and stay alliance-scoped',async()=>{const db=await attackFixture(),op=await createAttack(db);assert.deepEqual(op.targets[0].bookings.map(b=>b.landTick),[40,41,42]);assert.equal(op.phase,'Open');assert.equal((await api(db,'/api/alliance-operations','GET',null,'player-b')).data.operations.length,0);assert.equal((await api(db,'/api/alliance-operations','POST',{action:'close',generation:0,id:op.id,revision:0},'player-b')).status,404);assert.equal((await api(db,'/api/alliance-operations','POST',{action:'create',generation:9},'player-a')).status,409);});
test('simultaneous claims use operation revisions and only one member wins the wave',async()=>{const db=await attackFixture(true),op=await createAttack(db),payload={action:'claim',generation:0,id:op.id,revision:0,bookingId:op.targets[0].bookings[0].id};const claims=await Promise.all([api(db,'/api/alliance-operations','POST',payload),api(db,'/api/alliance-operations','POST',payload,'player-b')]);assert.deepEqual(claims.map(r=>r.status).sort(),[200,409]);const saved=(await api(db,'/api/alliance-operations')).data.operations.find(o=>o.id===op.id);assert.equal(saved.revision,1);assert.ok(['player-a','player-b'].includes(saved.targets[0].bookings[0].ownerId));});
test('shared booking owners must transfer before dropping; participants can save status',async()=>{const db=await attackFixture(true),op=await createAttack(db),booking=op.targets[0].bookings[0],base={generation:0,id:op.id,bookingId:booking.id};assert.equal((await api(db,'/api/alliance-operations','POST',{...base,action:'claim',revision:0})).status,200);assert.equal((await api(db,'/api/alliance-operations','POST',{...base,action:'share',revision:1,users:['player-b']})).status,200);assert.equal((await api(db,'/api/alliance-operations','POST',{...base,action:'drop',revision:2})).status,409);assert.equal((await api(db,'/api/alliance-operations','POST',{...base,action:'booking',revision:2,status:'land',notes:'Shared plan',group:'Vanguard',battleCalc:'Worksheet A'},'player-b')).status,200);assert.equal((await api(db,'/api/alliance-operations','POST',{...base,action:'transfer',revision:3,userId:'player-b'})).status,200);const saved=(await api(db,'/api/alliance-operations')).data.operations.find(o=>o.id===op.id).targets[0].bookings[0];assert.equal(saved.ownerId,'player-b');assert.deepEqual(saved.users,['player-a']);assert.equal(saved.status,'land');assert.equal((await api(db,'/api/alliance-operations','POST',{...base,action:'drop',revision:4})).status,200);});
test('scheduled target details stay hidden from members until prerelease',async()=>{const db=await attackFixture(true),op=await createAttack(db,{releaseAt:Date.now()+600000,prereleaseAt:Date.now()+300000});const member=(await api(db,'/api/alliance-operations','GET',null,'player-b')).data.operations.find(o=>o.id===op.id);assert.equal(member.phase,'Scheduled');assert.equal(member.targets.length,0);assert.equal((await api(db,'/api/alliance-operations','POST',{action:'claim',generation:0,id:op.id,revision:0,bookingId:op.targets[0].bookings[0].id},'player-b')).status,409);assert.equal((await api(db,'/api/alliance-operations','POST',{action:'release',generation:0,id:op.id,revision:0})).status,200);assert.equal((await api(db,'/api/alliance-operations','GET',null,'player-b')).data.operations.find(o=>o.id===op.id).targets.length,1);});
test('booked last waves cannot be removed or retimed and reset generations isolate operations',async()=>{const db=await attackFixture(),op=await createAttack(db),base={generation:0,id:op.id};assert.equal((await api(db,'/api/alliance-operations','POST',{...base,action:'claim',revision:0,bookingId:op.targets[0].bookings[2].id})).status,200);assert.equal((await api(db,'/api/alliance-operations','POST',{...base,action:'removeWave',revision:1})).status,409);assert.equal((await api(db,'/api/alliance-operations','POST',{...base,action:'edit',revision:1,title:'Updated',notes:'Plan',landTick:50})).status,409);db.sqlite.prepare('UPDATE planet_directory_meta SET reset_generation=1').run();assert.equal((await api(db,'/api/alliance-operations')).data.operations.length,0);assert.equal((await api(db,'/api/alliance-operations','POST',{...base,action:'close',revision:1})).status,409);});
test('legacy target imports preserve claims once without reopening closed operations',async()=>{const db=await attackFixture();assert.equal((await api(db,'/api/alliance-attack','POST',{action:'create',coords:'07:05:01',title:'Legacy target',notes:'Keep this'})).status,200);const target=(await api(db,'/api/alliance-attack')).data.targets[0];assert.equal((await api(db,'/api/alliance-attack','POST',{action:'claim',id:target.id})).status,200);const op=(await api(db,'/api/alliance-operations')).data.operations[0];assert.equal(op.legacy,true);assert.equal(op.targets[0].bookings[0].ownerId,'player-a');assert.equal((await api(db,'/api/alliance-operations','POST',{action:'close',generation:0,id:op.id,revision:0})).status,200);const refreshed=(await api(db,'/api/alliance-operations')).data.operations;assert.equal(refreshed.length,1);assert.equal(refreshed[0].phase,'Closed');});

test('Portal and Game diagnostic reports retain distinct scopes in stored history',async()=>{const db=database();await seed(db);for(const scope of ['portal','game']){const report=await api(db,'/api/staff/diagnostics','POST',{scope,observations:[],sampledPages:scope==='game'?8:6});assert.equal(report.status,200);assert.equal(report.data.report.scope,scope);assert.equal(report.data.report.sampleMode,scope==='game'?'isolated-read-only':'portal-pages');assert.equal((await api(db,'/api/staff/diagnostics?id='+report.data.report.id)).data.report.scope,scope);}const reports=(await api(db,'/api/staff/diagnostics')).data.reports;assert.deepEqual(reports.map(r=>r.scope).sort(),['game','portal']);assert.equal((await api(db,'/api/staff/diagnostics','POST',{scope:'invented'})).status,400);assert.equal((await api(db,'/game-diagnostic.html','GET',null,'player-b')).status,403);});

