const galaxyTradeSnapshot=db=>JSON.stringify({planet:galaxyTradePlanet(db),fund:db.sqlite.prepare('SELECT * FROM galaxy_development').all(),meta:db.sqlite.prepare('SELECT * FROM planet_directory_meta').all(),trades:db.sqlite.prepare('SELECT * FROM galaxy_fund_trades').all()});
async function galaxyTradeBody(db,extra={}){const quote=(await api(db,'/api/galaxy-development')).data;return {action:'trade',generation:quote.generation,revision:quote.revision,id:'galaxy-trade-default',from:'metal',to:'crystal',amount:100,...extra};}
test('Galaxy Fund exchange conserves each resource and records signed cumulative settlements',async()=>{const db=await galaxyTradeFixture(),before=galaxyTradePlanet(db),body=await galaxyTradeBody(db),result=await api(db,'/api/galaxy-development','POST',body);assert.equal(result.status,200,JSON.stringify(result.data));let p=galaxyTradePlanet(db),fund=JSON.parse(db.sqlite.prepare('SELECT data_json FROM galaxy_development WHERE galaxy=?').get(result.data.trade.galaxy).data_json).fund;assert.equal(p.resources.metal,before.resources.metal-100);assert.equal(p.resources.crystal,before.resources.crystal+99);assert.equal(p.resources.metal+fund.metal,before.resources.metal+700);assert.equal(p.resources.crystal+fund.crystal,before.resources.crystal+499);assert.deepEqual(p.bankTradeTotal,{metal:-100,crystal:99});assert.equal((await api(db,'/api/galaxy-development','POST',await galaxyTradeBody(db,{id:'galaxy-trade-second',from:'crystal',to:'eonium',amount:40}))).status,200);p=galaxyTradePlanet(db);assert.deepEqual(p.bankTradeTotal,{metal:-100,crystal:59,eonium:39});assert.equal((await api(db,'/api/galaxy-development')).data.trades.length,2);});
test('Galaxy Fund rejects unaffordable, depleted, stale-generation and stale-revision exchanges without writes',async()=>{for(const [extra,status]of [[{amount:100001},400],[{amount:501},409],[{generation:9},409],[{revision:-1},409],[{from:'metal',to:'metal'},400],[{amount:1.5},400]]){const db=await galaxyTradeFixture(),body=await galaxyTradeBody(db,extra),before=galaxyTradeSnapshot(db),r=await api(db,'/api/galaxy-development','POST',body);assert.equal(r.status,status,JSON.stringify(r.data));assert.equal(galaxyTradeSnapshot(db),before);}});
test('Galaxy Fund duplicate IDs pay once and reject conflicting payloads and other owners',async()=>{const db=await galaxyTradeFixture(),body=await galaxyTradeBody(db);assert.equal((await api(db,'/api/galaxy-development','POST',body)).status,200);const settled=galaxyTradeSnapshot(db),retry=await api(db,'/api/galaxy-development','POST',body);assert.equal(retry.status,200);assert.equal(retry.data.duplicate,true);assert.equal(galaxyTradeSnapshot(db),settled);assert.equal((await api(db,'/api/galaxy-development','POST',{...body,amount:99})).status,409);assert.equal(galaxyTradeSnapshot(db),settled);db.sqlite.prepare('INSERT INTO planet_directory VALUES(?,?,?,?,?,?)').run('trade-peer','planet','07:04:02','player-b',JSON.stringify({id:'trade-peer',ruler:'Peer',coords:'07:04:02',resources:{metal:1000}}),Date.now());await api(db,'/api/galaxy-development','GET',null,'player-b');assert.equal((await api(db,'/api/galaxy-development','POST',body,'player-b')).status,409);assert.equal(db.sqlite.prepare('SELECT count(*) n FROM galaxy_fund_trades').get().n,1);});
test('Galaxy Fund transaction rolls back planet, reserves, receipt and revision on receipt failure',async()=>{const db=await galaxyTradeFixture(),body=await galaxyTradeBody(db),before=galaxyTradeSnapshot(db);db.sqlite.exec("CREATE TRIGGER fail_galaxy_receipt BEFORE INSERT ON galaxy_fund_trades BEGIN SELECT RAISE(ABORT,'fixture receipt failure'); END;");const r=await api(db,'/api/galaxy-development','POST',body);assert.equal(r.status,503);assert.equal(galaxyTradeSnapshot(db),before);});
test('Galaxy Fund settlement fences stale colony reports until the exact cumulative counters are acknowledged',async()=>{const db=await galaxyTradeFixture(),report=colonyFixture();assert.equal((await api(db,'/api/galaxy-development','POST',await galaxyTradeBody(db))).status,200);const before=galaxyTradeSnapshot(db);const stale=await api(db,'/api/colony','POST',report);assert.equal(stale.status,409);assert.match(stale.data.error,/Bank settlement/);assert.equal(galaxyTradeSnapshot(db),before);const p=galaxyTradePlanet(db);assert.equal((await api(db,'/api/colony','POST',{...report,resources:p.resources,appliedBankTrades:p.bankTradeTotal})).status,200);assert.deepEqual(galaxyTradePlanet(db).resources,p.resources);assert.equal((await api(db,'/api/colony','POST',{...report,resources:p.resources,appliedBankTrades:{metal:-99,crystal:100}})).status,409);});

async function allianceBankFixture(rank='HC'){const db=database();await seed(db);await api(db,'/api/colony','POST',colonyFixture());const row=db.sqlite.prepare("SELECT data_json FROM planet_alliances WHERE name='Pact'").get(),a=JSON.parse(row.data_json);a.fund={metal:10000,crystal:10000,eonium:10000};a.members[0].rank=rank;a.fundMinimum={metal:100,crystal:100,eonium:100};db.sqlite.prepare("UPDATE planet_alliances SET data_json=? WHERE name='Pact'").run(JSON.stringify(a));return db;}
const allianceBankFund=db=>JSON.parse(db.sqlite.prepare("SELECT data_json FROM planet_alliances WHERE name='Pact'").get().data_json).fund;
async function allianceBankBody(db,extra={}){const q=(await api(db,'/api/spacing-bank')).data;return {action:'allianceTrade',id:'alliance-trade-test',generation:q.generation,revision:q.revision,directoryRevision:q.directoryRevision,from:'metal',to:'crystal',amount:100,...extra};}
const allianceBankSnapshot=db=>JSON.stringify({alliance:db.sqlite.prepare('SELECT * FROM planet_alliances').all(),planet:db.sqlite.prepare('SELECT * FROM planet_directory').all(),bank:db.sqlite.prepare('SELECT * FROM spacing_bank_round').all(),meta:db.sqlite.prepare('SELECT * FROM planet_directory_meta').all(),trades:db.sqlite.prepare('SELECT * FROM spacing_bank_trades').all()});
test('Alliance bank exchange is finite, fee-bearing and changes only alliance and bank reserves',async()=>{const db=await allianceBankFixture(),before=galaxyTradePlanet(db),q=(await api(db,'/api/spacing-bank')).data,b=await allianceBankBody(db),r=await api(db,'/api/spacing-bank','POST',b);assert.equal(r.status,200,JSON.stringify(r.data));assert.equal(r.data.trade.fee,5);assert.deepEqual(allianceBankFund(db),{metal:9900,crystal:10095,eonium:10000});assert.deepEqual(galaxyTradePlanet(db).resources,before.resources);const next=(await api(db,'/api/spacing-bank')).data;assert.equal(next.balances.metal,q.balances.metal+100);assert.equal(next.balances.crystal,q.balances.crystal-95);assert.equal(next.alliance.history.length,1);assert.equal(next.alliance.canTrade,true);});
test('Alliance exchange permits HC and Officer but rejects ordinary members and staff outsiders',async()=>{for(const rank of ['HC','Officer','Member','Scanner','Recruit']){const db=await allianceBankFixture(rank),body=await allianceBankBody(db);assert.equal((await api(db,'/api/spacing-bank','POST',body)).status,['HC','Officer'].includes(rank)?200:403);}const db=await allianceBankFixture();const q=(await api(db,'/api/spacing-bank','GET',null,'player-b')).data;assert.equal((await api(db,'/api/spacing-bank','POST',{...(await allianceBankBody(db)),directoryRevision:q.directoryRevision},'player-b')).status,403);});
test('Alliance bank rejects stale quotes and minimum violations without changes, duplicate settles once',async()=>{for(const extra of [{generation:99},{revision:-1},{directoryRevision:-1},{amount:9950}]){const db=await allianceBankFixture(),body=await allianceBankBody(db,extra),before=allianceBankSnapshot(db);assert.equal((await api(db,'/api/spacing-bank','POST',body)).status,409);assert.equal(allianceBankSnapshot(db),before);}const db=await allianceBankFixture(),body=await allianceBankBody(db);assert.equal((await api(db,'/api/spacing-bank','POST',body)).status,200);const before=allianceBankSnapshot(db),r=await api(db,'/api/spacing-bank','POST',body);assert.equal(r.status,200);assert.equal(r.data.duplicate,true);assert.equal(allianceBankSnapshot(db),before);assert.equal((await api(db,'/api/spacing-bank','POST',{...body,amount:99})).status,409);});
test('Alliance bank receipt failure atomically rolls back both funds and revisions',async()=>{const db=await allianceBankFixture(),body=await allianceBankBody(db),before=allianceBankSnapshot(db);db.sqlite.exec("CREATE TRIGGER reject_alliance_trade BEFORE INSERT ON spacing_bank_trades BEGIN SELECT RAISE(ABORT,'fixture bank failure'); END;");assert.equal((await api(db,'/api/spacing-bank','POST',body)).status,503);assert.equal(allianceBankSnapshot(db),before);});
test('Personal alliance exchange retains rounded-up fee, conserves balances and fences colony replay',async()=>{const db=await allianceBankFixture(),before=galaxyTradePlanet(db),body=await allianceBankBody(db,{action:'personalAllianceTrade',amount:101}),r=await api(db,'/api/spacing-bank','POST',body);assert.equal(r.status,200,JSON.stringify(r.data));assert.equal(r.data.trade.fee,3);assert.equal(r.data.trade.receive,98);assert.deepEqual(allianceBankFund(db),{metal:10101,crystal:9899,eonium:10000});const p=galaxyTradePlanet(db);assert.equal(p.resources.metal,before.resources.metal-101);assert.equal(p.resources.crystal,before.resources.crystal+98);assert.deepEqual(p.bankTradeTotal,{metal:-101,crystal:98});assert.equal((await api(db,'/api/colony','POST',colonyFixture())).status,409);const snapshot=allianceBankSnapshot(db);assert.equal((await api(db,'/api/spacing-bank','POST',body)).data.duplicate,true);assert.equal(allianceBankSnapshot(db),snapshot);});

test('Directory sync cannot overwrite centrally settled alliance reserves or strip the settlement marker',async()=>{const db=await allianceBankFixture(),before=(await api(db,'/api/planets')).data;assert.equal((await api(db,'/api/spacing-bank','POST',await allianceBankBody(db))).status,200);const latest=(await api(db,'/api/planets')).data,payload={revision:latest.revision,planets:latest.planets.map(p=>({...p,player:p.id==='home'})),structures:latest.structures,alliances:before.alliances};const snapshot=allianceBankSnapshot(db);const denied=await api(db,'/api/planets','POST',payload);assert.equal(denied.status,409,JSON.stringify(denied.data));assert.match(denied.data.error,/centrally settled/);assert.equal(allianceBankSnapshot(db),snapshot);payload.alliances=latest.alliances.map(a=>{const copy={...a};delete copy.fundSettlementVersion;return copy;});assert.equal((await api(db,'/api/planets','POST',payload)).status,200);const stored=JSON.parse(db.sqlite.prepare("SELECT data_json FROM planet_alliances WHERE name='Pact'").get().data_json);assert.equal(stored.fundSettlementVersion,1);assert.deepEqual(stored.fund,{metal:9900,crystal:10095,eonium:10000});});

test('Personal alliance exchange checks exchange permission and personal/fund stock, with atomic rollback',async()=>{for(const rank of ['Member','Recruit']){const db=await allianceBankFixture(rank),b=await allianceBankBody(db,{action:'personalAllianceTrade'}),before=allianceBankSnapshot(db);assert.equal((await api(db,'/api/spacing-bank','POST',b)).status,403);assert.equal(allianceBankSnapshot(db),before);}for(const [amount,status]of [[100001,400],[20000,409]]){const db=await allianceBankFixture(),b=await allianceBankBody(db,{action:'personalAllianceTrade',amount}),before=allianceBankSnapshot(db);assert.equal((await api(db,'/api/spacing-bank','POST',b)).status,status);assert.equal(allianceBankSnapshot(db),before);}const db=await allianceBankFixture(),b=await allianceBankBody(db,{action:'personalAllianceTrade'}),before=allianceBankSnapshot(db);db.sqlite.exec("CREATE TRIGGER reject_personal_alliance_trade BEFORE INSERT ON spacing_bank_trades BEGIN SELECT RAISE(ABORT,'fixture failure'); END;");assert.equal((await api(db,'/api/spacing-bank','POST',b)).status,503);assert.equal(allianceBankSnapshot(db),before);});
test('Alliance bank honours finite universal reserves and rejects a lost directory CAS without partial settlement',async()=>{const db=await allianceBankFixture(),b=await allianceBankBody(db),row=db.sqlite.prepare('SELECT * FROM spacing_bank_round').get(),data=JSON.parse(row.data_json);data.balances.crystal=1;db.sqlite.prepare('UPDATE spacing_bank_round SET data_json=? WHERE generation=?').run(JSON.stringify(data),row.generation);let before=allianceBankSnapshot(db);assert.equal((await api(db,'/api/spacing-bank','POST',b)).status,409);assert.equal(allianceBankSnapshot(db),before);data.balances.crystal=1000000;db.sqlite.prepare('UPDATE spacing_bank_round SET data_json=? WHERE generation=?').run(JSON.stringify(data),row.generation);const original=db.batch.bind(db);let injected=false;db.batch=async statements=>{if(!injected){injected=true;db.sqlite.prepare('UPDATE planet_directory_meta SET revision=revision+1 WHERE id=1').run();}return original(statements);};const planetBefore=JSON.stringify(galaxyTradePlanet(db)),fundBefore=JSON.stringify(allianceBankFund(db));assert.equal((await api(db,'/api/spacing-bank','POST',await allianceBankBody(db))).status,409);assert.equal(JSON.stringify(galaxyTradePlanet(db)),planetBefore);assert.equal(JSON.stringify(allianceBankFund(db)),fundBefore);assert.equal(db.sqlite.prepare("SELECT count(*) n FROM spacing_bank_trades WHERE id=?").get(b.id).n,0);});

test('Personal alliance fees settle into Universal Bank exactly once with three-treasury conservation',async()=>{const db=await allianceBankFixture(),q=(await api(db,'/api/spacing-bank')).data,p0=galaxyTradePlanet(db).resources,f0=allianceBankFund(db),body=await allianceBankBody(db,{action:'personalAllianceTrade',amount:101}),result=await api(db,'/api/spacing-bank','POST',body);assert.equal(result.status,200);assert.equal(result.data.trade.feeDestination,'Universal Bank');assert.equal(result.data.trade.bankFeeResource,'crystal');const after=(await api(db,'/api/spacing-bank')).data,p1=galaxyTradePlanet(db).resources,f1=allianceBankFund(db);for(const k of ['metal','crystal','eonium'])assert.equal(p1[k]+f1[k]+after.balances[k],p0[k]+f0[k]+q.balances[k]);assert.equal(after.balances.crystal,q.balances.crystal+3);assert.equal(after.taxCollected.crystal,q.taxCollected.crystal+3);assert.equal(after.revision,q.revision+1);const settled=allianceBankSnapshot(db);assert.equal((await api(db,'/api/spacing-bank','POST',body)).data.duplicate,true);assert.equal(allianceBankSnapshot(db),settled);});

test('Galaxy Fund 1% fee credits Universal Bank once and conserves three treasuries atomically',async()=>{const db=await galaxyTradeFixture(),bank0=(await api(db,'/api/spacing-bank')).data,body=await galaxyTradeBody(db,{amount:101}),p0=galaxyTradePlanet(db).resources,f0=(await api(db,'/api/galaxy-development')).data.fund,r=await api(db,'/api/galaxy-development','POST',body);assert.equal(r.status,200,JSON.stringify(r.data));assert.equal(r.data.trade.fee,2);assert.equal(r.data.trade.receive,99);assert.equal(r.data.trade.feeDestination,'Universal Bank');const bank1=(await api(db,'/api/spacing-bank')).data,p1=galaxyTradePlanet(db).resources,f1=(await api(db,'/api/galaxy-development')).data.fund;for(const k of ['metal','crystal','eonium'])assert.equal(p1[k]+f1[k]+bank1.balances[k],p0[k]+f0[k]+bank0.balances[k]);assert.equal(bank1.balances.crystal,bank0.balances.crystal+2);assert.equal(bank1.taxCollected.crystal,bank0.taxCollected.crystal+2);assert.equal(bank1.revision,bank0.revision+1);const snapshot=allianceBankSnapshot(db);assert.equal((await api(db,'/api/galaxy-development','POST',body)).data.duplicate,true);assert.equal(allianceBankSnapshot(db),snapshot);});
test('Galaxy Fund gross target funding and Universal Bank fee rollback are enforced',async()=>{const db=await galaxyTradeFixture();await api(db,'/api/spacing-bank');const insufficient=await galaxyTradeBody(db,{amount:501});assert.equal((await api(db,'/api/galaxy-development','POST',insufficient)).status,409);const body=await galaxyTradeBody(db),before=allianceBankSnapshot(db),fundBefore=galaxyTradeSnapshot(db);db.sqlite.exec("CREATE TRIGGER reject_galaxy_fee BEFORE INSERT ON galaxy_fund_trades BEGIN SELECT RAISE(ABORT,'fee rollback'); END;");assert.equal((await api(db,'/api/galaxy-development','POST',body)).status,503);assert.equal(allianceBankSnapshot(db),before);assert.equal(galaxyTradeSnapshot(db),fundBefore);});

async function residentTaxFixture(full=false){const db=database();await seed(db);db.sqlite.exec('CREATE TABLE IF NOT EXISTS galaxy_distribution(id INTEGER PRIMARY KEY,generation INTEGER NOT NULL,shuffled INTEGER NOT NULL DEFAULT 0,at_tick INTEGER NOT NULL DEFAULT 0);INSERT OR REPLACE INTO galaxy_distribution VALUES(1,0,1,12);');const p=galaxyTradePlanet(db);Object.assign(p,{planetType:'planet-01',population:full?1050:900,publicPopulation:full?1050:900,publicTick:10,buildings:{biodome:full?1:0},research:{demography:0},resources:{metal:1000,crystal:1000,eonium:1000}});db.sqlite.prepare("UPDATE planet_directory SET data_json=? WHERE id='home'").run(JSON.stringify(p));await api(db,'/api/galaxy-development');return db;}
async function residentTaxReport(db,tick){const p=galaxyTradePlanet(db);return api(db,'/api/colony','POST',{...colonyFixture(p.population,p.buildings.biodome),publicTick:tick,resources:p.resources,research:p.research,appliedTaxTotal:p.populationTaxTotal||0});}
test('Population overflow at verified full housing creates fund resources at rate zero without removing residents',async()=>{const db=await residentTaxFixture(true);assert.equal((await residentTaxReport(db,11)).status,200);let p=galaxyTradePlanet(db),d=(await api(db,'/api/galaxy-development')).data;assert.equal(p.population,1050);assert.equal(p.populationTaxTotal,0);assert.equal(d.ownTax.overflowTotal,4);assert.ok(Math.abs(d.ownTax.overflowCarry-.2825)<1e-9);assert.equal(d.fund.metal,24);assert.equal(d.history[0].removed,0);assert.equal(d.history[0].overflowConverted,4);assert.equal((await residentTaxReport(db,12)).status,200);d=(await api(db,'/api/galaxy-development')).data;assert.equal(d.ownTax.overflowTotal,8);assert.equal(d.fund.metal,48);assert.ok(Math.abs(d.ownTax.overflowCarry-.565)<1e-9);assert.equal((await residentTaxReport(db,12)).status,200);assert.equal((await api(db,'/api/galaxy-development')).data.fund.metal,48);});
test('Population resident levy settles only the reporting planet and never unadvanced galaxy peers',async()=>{const db=await residentTaxFixture(),p=galaxyTradePlanet(db);db.sqlite.prepare('INSERT INTO planet_directory VALUES(?,?,?,?,?,?)').run('tax-peer','planet',p.coords.slice(0,6)+'02','player-b',JSON.stringify({...p,id:'tax-peer',coords:p.coords.slice(0,6)+'02',ruler:'Peer'}),Date.now());const row=db.sqlite.prepare('SELECT * FROM galaxy_development WHERE galaxy=?').get(p.coords.split(':').slice(0,2).join(':')),d=JSON.parse(row.data_json);d.tax=5;d.carry={home:1000,'tax-peer':1000};db.sqlite.prepare('UPDATE galaxy_development SET data_json=? WHERE galaxy=?').run(JSON.stringify(d),row.galaxy);const peerBefore=db.sqlite.prepare("SELECT data_json FROM planet_directory WHERE id='tax-peer'").get().data_json;for(let tick=11;tick<=34;tick++){const report=await residentTaxReport(db,tick);assert.equal(report.status,200);assert.equal(report.data.taxTotal,galaxyTradePlanet(db).populationTaxTotal||0);}const settled=galaxyTradePlanet(db);assert.equal(settled.populationTaxTotal,5);assert.equal(settled.population,895);assert.equal(db.sqlite.prepare("SELECT data_json FROM planet_directory WHERE id='tax-peer'").get().data_json,peerBefore);const stats=(await api(db,'/api/galaxy-development')).data;assert.equal(stats.ownTax.removedInWindow,5);assert.equal(stats.fund.metal,30);});
test('Interrupted population levy preserves a durable report and recovers exactly once on same-tick retry',async()=>{const db=await residentTaxFixture(true);db.sqlite.exec("CREATE TRIGGER interrupt_population_settlement BEFORE UPDATE ON galaxy_development WHEN json_extract(NEW.data_json,'$.history[0].tick')=11 BEGIN SELECT RAISE(ABORT,'fixture levy interruption'); END;");const first=await residentTaxReport(db,11);assert.notEqual(first.status,200);let p=galaxyTradePlanet(db);assert.equal(p.publicTick,11);assert.equal(p.pendingPopulationTaxReport.tick,11);assert.equal(p.populationTaxOverflowTotal||0,0);db.sqlite.exec('DROP TRIGGER interrupt_population_settlement');assert.equal((await residentTaxReport(db,11)).status,200);p=galaxyTradePlanet(db);assert.equal(p.population,1050);assert.equal(p.populationTaxOverflowTotal,4);assert.equal(p.pendingPopulationTaxReport,undefined);const d=(await api(db,'/api/galaxy-development')).data;assert.equal(d.fund.metal,24);assert.equal((await residentTaxReport(db,11)).status,200);assert.equal((await api(db,'/api/galaxy-development')).data.fund.metal,24);});

test('Population levy settings and history use resident units rather than percentages',async()=>{const db=await residentTaxFixture(),p=galaxyTradePlanet(db),ministers={communication:'',development:p.ruler,war:'',economics:p.ruler,scanner:''};assert.equal((await api(db,'/api/galaxy-development','POST',{action:'ministers',ministers,generation:0})).status,200);assert.equal((await api(db,'/api/galaxy-development','POST',{action:'tax',rate:4,generation:0})).status,200);const d=(await api(db,'/api/galaxy-development')).data;assert.match(d.log[0].text,/4 residents per planet per 24 ticks/);assert.doesNotMatch(d.log[0].text,/%/);const bad=await api(db,'/api/galaxy-development','POST',{action:'tax',rate:6,generation:0});assert.match(bad.data.error,/residents per planet per 24 ticks/);});

async function governmentEditPayload(db,request){const d=(await api(db,'/api/planets')).data;return {revision:d.revision,planets:d.planets.map(p=>p.id==='home'?{...p,adminGovernmentRequest:request}:p),structures:d.structures,alliances:d.alliances,source:'staff-editor'};}
test('Staff government override applies immediately, clears anarchy and reaches its owner as a one-time command',async()=>{const db=database();await seed(db);const p=galaxyTradePlanet(db);Object.assign(p,{government:'Anarchy',governmentPending:'Democracy',governmentRevolutionUntil:999});db.sqlite.prepare("UPDATE planet_directory SET data_json=? WHERE id='home'").run(JSON.stringify(p));const request={id:'government-command-001',government:'Socialism'},payload=await governmentEditPayload(db,request);assert.equal((await api(db,'/api/planets','POST',payload)).status,200);const after=galaxyTradePlanet(db);assert.equal(after.government,'Socialism');assert.equal(after.governmentPending,null);assert.equal(after.governmentRevolutionUntil,0);assert.equal(after.adminGovernmentRequest,undefined);assert.equal(after.governmentOverride.government,'Socialism');assert.equal(after.governmentOverride.by,'player-a');const command=after.governmentOverride.id;assert.equal((await api(db,'/api/planets','POST',await governmentEditPayload(db,request))).status,200);assert.equal(galaxyTradePlanet(db).governmentOverride.id,command);const latest=(await api(db,'/api/planets')).data;assert.equal(latest.planets.find(p=>p.id==='home').governmentOverride.id,command);});
test('Government override rejects unauthorised staff nodes, transient anarchy and conflicting command IDs',async()=>{const db=database();await seed(db);let body=await governmentEditPayload(db,{id:'government-command-002',government:'Democracy'});assert.equal((await api(db,'/api/planets','POST',body,'player-b')).status,403);assert.equal((await api(db,'/api/planets','POST',body)).status,200);body=await governmentEditPayload(db,{id:'government-command-002',government:'Nationalism'});assert.equal((await api(db,'/api/planets','POST',body)).status,409);body=await governmentEditPayload(db,{id:'government-command-003',government:'Anarchy'});assert.equal((await api(db,'/api/planets','POST',body)).status,400);assert.equal(galaxyTradePlanet(db).government,'Democracy');db.sqlite.prepare("UPDATE portal_users SET role='support' WHERE id='player-a'").run();assert.equal((await api(db,'/api/planets','POST',body)).status,403);});
test('Ordinary staff directory synchronization preserves the latest government command against stale fields',async()=>{const db=database();await seed(db);assert.equal((await api(db,'/api/planets','POST',await governmentEditPayload(db,{id:'government-command-004',government:'Corporatism'}))).status,200);const before=galaxyTradePlanet(db),d=(await api(db,'/api/planets')).data,payload={revision:d.revision,planets:d.planets.map(p=>({...p,government:'Anarchy',governmentPending:'Socialism',governmentRevolutionUntil:888,governmentOverride:{id:'forged'}})),structures:d.structures,alliances:d.alliances};assert.equal((await api(db,'/api/planets','POST',payload)).status,200);const after=galaxyTradePlanet(db);assert.equal(after.government,'Corporatism');assert.equal(after.governmentPending,null);assert.equal(after.governmentRevolutionUntil,0);assert.equal(after.governmentOverride.id,before.governmentOverride.id);});

async function centralShipyardFixture(){const db=database();await seed(db);seedOtherAlliance(db);const a=JSON.parse(db.sqlite.prepare("SELECT data_json FROM planet_alliances WHERE name='Pact'").get().data_json);a.fund={metal:100000000,crystal:100000000,eonium:100000000};a.members.push({id:'shipyard-member',planetId:'other-home',planet:'Other Home',name:'Other',rank:'Member'});db.sqlite.prepare("UPDATE planet_alliances SET data_json=? WHERE name='Pact'").run(JSON.stringify(a));for(const id of ['home','other-home']){const p=JSON.parse(db.sqlite.prepare('SELECT data_json FROM planet_directory WHERE id=?').get(id).data_json);Object.assign(p,{alliance:'Pact',publicTick:30,buildings:{lightFactory:3,mediumFactory:3,heavyFactory:3},research:{fighter:3,cargo:1},workforce:{shipwright:0},race:id==='home'?'Terran':'Cathaar'});db.sqlite.prepare('UPDATE planet_directory SET data_json=? WHERE id=?').run(JSON.stringify(p),id);}return db;}
async function centralShipyardCommand(db,action,extra={},user='player-a'){const d=(await api(db,'/api/alliance-shipyards','GET',null,user)).data;return {action,id:'shipyard-'+require('node:crypto').randomUUID(),generation:d.generation,revision:d.revision,directoryRevision:d.directoryRevision,...extra};}
test('Real Shipyards route delivers current-member mixed hulls only as existing f4 provenance and fences stale Launch Bay readiness',async()=>{const db=await centralShipyardFixture();assert.equal((await api(db,'/api/alliance-shipyards','GET',null,'player-b')).status,403);let q=(await api(db,'/api/alliance-shipyards')).data;assert.ok(q.catalog.some(s=>s.race==='Cathaar'));assert.equal(q.factories.count.lightFactory,6);const order=await centralShipyardCommand(db,'order',{items:[{shipId:'terran-lumen',quantity:100,planetId:'other-home'}]});assert.equal((await api(db,'/api/alliance-shipyards','POST',order)).status,200);const p=galaxyTradePlanet(db);p.publicTick=36;db.sqlite.prepare("UPDATE planet_directory SET data_json=? WHERE id='home'").run(JSON.stringify(p));db.sqlite.prepare('UPDATE planet_directory_meta SET revision=revision+1').run();q=(await api(db,'/api/alliance-shipyards')).data;assert.equal(q.orders[0].status,'Delivered');const mine=(await api(db,'/api/alliance-shipyards?mine=1','GET',null,'player-b')).data;assert.equal(mine.allianceName,'Pact');assert.equal(mine.inventory.planetId,'other-home');assert.equal(mine.inventory.available['terran-lumen'],100);assert.equal(mine.inventory.deliveryTotals['terran-lumen'],100);const readiness={action:'snapshot',generation:0,resetEpoch:0,tick:36,shipyardRevision:q.revision,fleets:{f4:{'terran-lumen':100}}};assert.equal((await api(db,'/api/alliance-fleets','POST',{...readiness,shipyardRevision:q.revision-1},'player-b')).status,409);assert.equal((await api(db,'/api/alliance-fleets','POST',readiness,'player-b')).status,200);const sale=await centralShipyardCommand(db,'sell',{items:[{shipId:'terran-lumen',quantity:20,planetId:'other-home'}]});assert.equal((await api(db,'/api/alliance-shipyards','POST',sale)).status,200);const launch={action:'launch',generation:0,planetId:'other-home',targetId:'home',targetResetEpoch:0,mission:'Defence',delay:0};const stale=await api(db,'/api/alliance-fleets','POST',launch);assert.equal(stale.status,409);assert.match(stale.data.error,/Alliance Ships changed/);const latest=(await api(db,'/api/alliance-shipyards?mine=1','GET',null,'player-b')).data;assert.equal(latest.inventory.available['terran-lumen'],80);assert.equal(latest.inventory.removalTotals['terran-lumen'],20);assert.equal((await api(db,'/api/alliance-fleets','POST',{...readiness,shipyardRevision:latest.revision,fleets:{f4:{'terran-lumen':80}}},'player-b')).status,200);assert.equal((await api(db,'/api/alliance-fleets','POST',launch)).status,200);});
test('manual and automatic shuffle leave every 1:1 planet at its exact protected coordinates',async()=>{for(const automatic of [false,true]){const db=database();await seed(db);await enrol(db,'player-b');const raw=db.sqlite.prepare("SELECT data_json FROM planet_directory WHERE id='home'").get();const p=JSON.parse(raw.data_json);p.coords='01:01:01';p.startingGalaxy=true;p.publicTick=11;db.sqlite.prepare("UPDATE planet_directory SET coords=?,data_json=? WHERE id='home'").run(p.coords,JSON.stringify(p));const before=JSON.stringify(p);if(automatic){const report={...colonyFixture(500,0),publicTick:12};assert.equal((await api(db,'/api/colony','POST',report)).status,200);}else{const r=await api(db,'/api/admin/shuffle','POST',{confirmation:'SHUFFLE'});assert.equal(r.status,200);assert.equal(r.data.planets,1);}const rows=db.sqlite.prepare('SELECT id,coords,data_json FROM planet_directory').all(),protectedHome=rows.find(row=>row.id==='home');assert.equal(protectedHome.coords,'01:01:01');assert.equal(JSON.parse(protectedHome.data_json).coords,'01:01:01');assert.equal(JSON.parse(protectedHome.data_json).startingGalaxy,true);if(!automatic)assert.equal(protectedHome.data_json,before);assert.ok(rows.find(row=>row.id!=='home').coords.startsWith('02:'));}});
test('requested shuffle-fix reset runs once as a migration and retains accounts and memorials',()=>{const db=new DatabaseSync(':memory:');for(const name of fs.readdirSync(path.join(__dirname,'../drizzle')).filter(n=>n.endsWith('.sql')&&!n.startsWith('0039')).sort())db.exec(fs.readFileSync(path.join(__dirname,'../drizzle',name),'utf8'));db.prepare('INSERT INTO portal_users(id,username,password_hash,password_salt,role,created_at) VALUES(?,?,?,?,?,?)').run('kept','Kept','hash','salt','admin',1);db.prepare('INSERT INTO planet_directory VALUES(?,?,?,?,?,?)').run('old','planet','01:01:01','kept',JSON.stringify({id:'old',planetType:'planet-01'}),1);db.prepare('INSERT INTO memorial_ghosts VALUES(?,?,?,?,?,?)').run('ghost','01:01:11','Memorial','','',1);const before=db.prepare('SELECT reset_generation FROM planet_directory_meta').get().reset_generation;db.exec(fs.readFileSync(path.join(__dirname,'../drizzle/0039_requested_shuffle_fix_round_reset.sql'),'utf8'));assert.equal(db.prepare('SELECT count(*) n FROM planet_directory').get().n,0);assert.equal(db.prepare('SELECT count(*) n FROM portal_users').get().n,1);assert.equal(db.prepare('SELECT count(*) n FROM memorial_ghosts').get().n,1);assert.equal(db.prepare('SELECT reset_generation FROM planet_directory_meta').get().reset_generation,before+1);assert.equal(db.prepare('SELECT confirmed FROM planet_enrolments WHERE user_id=?').get('kept').confirmed,0);});
test('round reset clears all forum scopes including General while retaining accounts',async()=>{const db=database();await seed(db);for(const scope of ['community','galaxy','alliance'])assert.equal((await api(db,'/api/forums','POST',{action:'thread',scope,title:'Reset '+scope,body:'Erase this round message'})).status,201);assert.equal(db.sqlite.prepare('SELECT count(*) n FROM forum_posts').get().n,3);assert.equal((await api(db,'/api/portal/reset','POST',{confirmation:'RESET'})).status,200);assert.equal(db.sqlite.prepare('SELECT count(*) n FROM forum_posts').get().n,0);assert.equal(db.sqlite.prepare('SELECT count(*) n FROM forum_threads').get().n,0);assert.equal(db.sqlite.prepare('SELECT count(*) n FROM portal_users').get().n,2);});
test('one-time forum cleanup does not reset the round or remove colonies',()=>{const db=new DatabaseSync(':memory:');db.exec(fs.readFileSync(path.join(__dirname,'../drizzle/0007_forums.sql'),'utf8'));db.exec('CREATE TABLE planet_directory(id TEXT);INSERT INTO planet_directory VALUES (\'keep\');CREATE TABLE planet_directory_meta(reset_generation INTEGER);INSERT INTO planet_directory_meta VALUES(26);');db.prepare('INSERT INTO forum_threads VALUES(?,?,?,?,?,?,?,?)').run('topic','community','','General','user','User',1,1);db.prepare('INSERT INTO forum_posts VALUES(?,?,?,?,?,?)').run('post','topic','user','User','Old message',1);db.exec(fs.readFileSync(path.join(__dirname,'../drizzle/0040_requested_all_forums_cleanup.sql'),'utf8'));assert.equal(db.prepare('SELECT count(*) n FROM forum_posts').get().n,0);assert.equal(db.prepare('SELECT count(*) n FROM planet_directory').get().n,1);assert.equal(db.prepare('SELECT reset_generation FROM planet_directory_meta').get().reset_generation,26);});
